<?php
namespace Tests\Feature;
use App\Models\Employee; use App\Models\EmployeeContract; use App\Models\Tenant; use App\Models\User; use App\Services\ContractService; use Carbon\Carbon; use Illuminate\Support\Str; use Tests\TestCase;
class ContractServiceTest extends TestCase { public function test_activation_supersedes_previous_contract_and_expiry_is_date_driven():void{if(config('database.default')!=='mysql')$this->markTestSkipped('Requires MySQL.');$tenant=Tenant::create(['name'=>'Contracts '.Str::random(5)]);try{tenancy()->initialize($tenant);$u=User::create(['name'=>'HR','email'=>Str::uuid().'@example.test','password'=>'secret123','role'=>'hr']);$e=Employee::create(['name'=>'Employee','national_id'=>'C-'.Str::uuid(),'hire_date'=>'2026-01-01','salary'=>'400.000','status'=>'active']);$s=app(ContractService::class);$a=$s->create($e,['type'=>'indefinite','start_date'=>'2026-01-01'],$u->id);$s->activate($a);$b=$s->create($e,['type'=>'fixed_term','start_date'=>'2026-06-01','end_date'=>'2026-09-10'],$u->id);$s->activate($b);$this->assertSame('superseded',$a->refresh()->status);$this->assertSame('active',$b->refresh()->status);$this->assertCount(1,$s->expiringWithin(Carbon::parse('2026-09-01'),30));$s->expireDue(Carbon::parse('2026-09-11'));$this->assertSame('expired',$b->refresh()->status);}finally{if(tenancy()->initialized)tenancy()->end();$tenant->delete();}} }
